using System.Collections.Concurrent;

public static class Throttle
{
    // شغّل 50 مهمة I/O بحد أقصى 8 في نفس الوقت، مع احترام الإلغاء.
    public static async Task<TResult[]> RunAsync<TResult>(
        IEnumerable<Func<CancellationToken, Task<TResult>>> jobs,
        int maxConcurrency = 8,
        CancellationToken ct = default)
    {
        ArgumentOutOfRangeException.ThrowIfLessThan(maxConcurrency, 1);

        using var gate = new SemaphoreSlim(maxConcurrency, maxConcurrency);
        var results = new ConcurrentBag<(int Index, TResult Value)>();

        var tasks = jobs.Select(async (job, index) =>
        {
            await gate.WaitAsync(ct).ConfigureAwait(false);
            try
            {
                var value = await job(ct).ConfigureAwait(false);
                results.Add((index, value));
            }
            finally
            {
                gate.Release();   // الإفراج في finally: خطأ في مهمة لا يجفف الحد
            }
        });

        await Task.WhenAll(tasks).ConfigureAwait(false);

        // أعِد الترتيب الأصلي — ConcurrentBag لا يحفظه.
        return results.OrderBy(r => r.Index).Select(r => r.Value).ToArray();
    }
}
